const button = document.getElementById('menu-button');
const menu = document.getElementById('site-menu');
const items = Array.from(menu.querySelectorAll('[role="menuitem"]'));

function isOpen() {
  return !menu.hidden;
}

function open() {
  menu.hidden = false;
  button.setAttribute('aria-expanded', 'true');
}

function close({ focusButton = false } = {}) {
  if (!isOpen()) return;
  menu.hidden = true;
  button.setAttribute('aria-expanded', 'false');
  if (focusButton) button.focus();
}

button.addEventListener('click', () => {
  isOpen() ? close() : open();
});

button.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    open();
    (e.key === 'ArrowDown' ? items[0] : items[items.length - 1]).focus();
  }
});

document.addEventListener('keydown', (e) => {
  if (!isOpen()) return;

  const activeIndex = items.indexOf(document.activeElement);

  switch (e.key) {
    case 'Escape':
      e.preventDefault();
      close({ focusButton: true });
      break;
    case 'ArrowDown':
      e.preventDefault();
      items[(activeIndex + 1) % items.length].focus();
      break;
    case 'ArrowUp':
      e.preventDefault();
      items[(activeIndex - 1 + items.length) % items.length].focus();
      break;
    case 'Home':
      e.preventDefault();
      items[0].focus();
      break;
    case 'End':
      e.preventDefault();
      items[items.length - 1].focus();
      break;
    case 'Tab': {
      // Tabbing out of an open menu closes it without swallowing the tab.
      const focusInMenu = menu.contains(document.activeElement) && activeIndex !== -1;
      if (focusInMenu) {
        const leavingForward = !e.shiftKey && activeIndex === items.length - 1;
        const leavingBackward = e.shiftKey && activeIndex === 0;
        if (leavingForward || leavingBackward) close();
      } else if (!menu.contains(document.activeElement)) {
        close();
      }
      break;
    }
  }
});

// Click outside closes the menu.
document.addEventListener('pointerdown', (e) => {
  if (isOpen() && !e.composedPath().includes(menu) && e.target !== button) {
    close();
  }
});

