import { test, expect } from '@playwright/test';

const button = '#menu-button';
const menu = '#site-menu';

test.beforeEach(async ({ page }) => {
  await page.goto('/');
  await expect(page.locator(button)).toHaveAttribute('aria-expanded', 'false');
  await expect(page.locator(menu)).toBeHidden();
});

test('opens with Enter and receives focusable items', async ({ page }) => {
  await page.locator(button).focus();
  await page.keyboard.press('Enter');

  await expect(page.locator(button)).toHaveAttribute('aria-expanded', 'true');
  await expect(page.locator(menu)).toBeVisible();

  // First ArrowDown moves focus to the first item.
  await page.keyboard.press('ArrowDown');
  await expect(page.locator('#menu-item-rename')).toBeFocused();
});

test('ArrowDown/ArrowUp move focus with wrap-around', async ({ page }) => {
  const item = (n) => page.locator(`#menu-item-${n}`);
  await page.locator(button).focus();
  await page.keyboard.press('Enter'); // open
  await page.keyboard.press('ArrowDown'); // -> Rename

  for (const name of ['duplicate', 'archive', 'delete']) {
    await page.keyboard.press('ArrowDown');
    await expect(item(name)).toBeFocused();
  }

  // Wrap forward: delete -> rename
  await page.keyboard.press('ArrowDown');
  await expect(item('rename')).toBeFocused();

  // Wrap backward: rename -> delete
  await page.keyboard.press('ArrowUp');
  await expect(item('delete')).toBeFocused();
  await page.keyboard.press('ArrowUp');
  await expect(item('archive')).toBeFocused();
});

test('keyboard navigation reaches the third item, asserted via activeElement text', async ({ page }) => {
  await page.locator(button).focus();
  await page.keyboard.press('Enter');
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('ArrowDown');

  await expect
    .poll(() => page.evaluate(() => document.activeElement?.textContent?.trim()))
    .toBe('Archive');
  await expect(page.locator('#menu-item-archive')).toBeFocused();
});

test('Escape closes the menu and returns focus to the button', async ({ page }) => {
  await page.locator(button).focus();
  await page.keyboard.press('Enter');
  await page.keyboard.press('ArrowDown');
  await expect(page.locator('#menu-item-rename')).toBeFocused();

  await page.keyboard.press('Escape');

  await expect(page.locator(button)).toHaveAttribute('aria-expanded', 'false');
  await expect(page.locator(menu)).toBeHidden();
  await expect(page.locator(button)).toBeFocused();
});

test('clicking outside closes the menu', async ({ page }) => {
  await page.locator(button).click();
  await expect(page.locator(button)).toHaveAttribute('aria-expanded', 'true');

  await page.locator('#outside-field').click();

  await expect(page.locator(button)).toHaveAttribute('aria-expanded', 'false');
  await expect(page.locator(menu)).toBeHidden();
});

test('Tabbing out of the menu closes it', async ({ page }) => {
  await page.locator(button).focus();
  await page.keyboard.press('Enter');
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('ArrowDown'); // last item (Delete)

  await page.keyboard.press('Tab'); // tab past the last item

  await expect(page.locator(button)).toHaveAttribute('aria-expanded', 'false');
  await expect(page.locator(menu)).toBeHidden();
});

